// P-GRD: trailing run guard properties at threshold boundaries. Each case
// plants a structurally valid candidate so the guard boundary is the only
// variable, and checks `swap` against the independent oracle. Payloads are
// constructed (never filtered): generated bytes exclude the planted literals
// so the planted span is identifiable without assuming global entry counts.
// Never read the session key, nonce, or ciphertext.

use crate::generators::{self, PatternSpec};
use crate::oracle::{Cs, Seg};
use proptest::prelude::*;

const ANCHOR_BYTES: &[u8] = b"abPQ";
const A_ANCHOR_BYTES: &[u8] = b"ab";
const B_ANCHOR_BYTES: &[u8] = b"PQ";

const GUARD_VAR_CS: [Cs; 4] = [
    Cs::UrlSafeBase64,
    Cs::UppercaseAlphanumeric,
    Cs::Alphanumeric,
    Cs::Digits,
];
const GUARD_CS: [Cs; 4] = [Cs::Base64Any, Cs::UrlSafeBase64, Cs::Alphanumeric, Cs::Wide];
const A_GUARD_CS: [Cs; 2] = [Cs::Wide, Cs::Base64Any];
const B_VAR_CS: [Cs; 3] = [Cs::Alphanumeric, Cs::UrlSafeBase64, Cs::Base64Any];

/// Deterministic alphabet from `cs` with `excluded` bytes removed. Guarantees a
/// planted literal cannot reappear inside generated bytes, so the planted
/// candidate span is the only place its anchor matches.
fn chars_excluding(cs: Cs, excluded: &[u8]) -> Vec<u8> {
    cs.bytes()
        .into_iter()
        .filter(|b| !excluded.contains(b))
        .collect()
}

/// `len` bytes from `cs` excluding `excluded`, biased 1:3 toward `+/-_` bytes
/// where those belong to `cs` (so base64 `+/` versus url-safe `-_` both occur).
fn arb_run(cs: Cs, len: usize, excluded: &[u8]) -> BoxedStrategy<Vec<u8>> {
    let full = chars_excluding(cs, excluded);
    let special: Vec<u8> = b"+/-_"
        .iter()
        .copied()
        .filter(|&b| cs.contains(b) && !excluded.contains(&b))
        .collect();
    let item = if special.is_empty() {
        prop::sample::select(full).boxed()
    } else {
        prop_oneof![
            1 => prop::sample::select(special),
            3 => prop::sample::select(full),
        ]
        .boxed()
    };
    prop::collection::vec(item, len..=len).boxed()
}

fn first_lit(spec: &PatternSpec) -> Vec<u8> {
    match spec.segs.first() {
        Some(Seg::Lit(bytes)) => bytes.clone(),
        other => panic!("expected literal first segment, got {other:?}"),
    }
}

fn var_seg(spec: &PatternSpec) -> (Cs, usize) {
    match spec.segs.get(1) {
        Some(Seg::Var(cs, n, _)) => (*cs, *n),
        other => panic!("expected fixed variable second segment, got {other:?}"),
    }
}

/// Guarded family spec: literal anchor, floor-length variable segment (its minimum
/// meets the fake-capacity floor), optional trailing `_`, threshold 1..=12,
/// inferred or explicit guard charset.
fn arb_guarded_spec() -> impl Strategy<Value = PatternSpec> {
    (
        prop::collection::vec(prop::sample::select(ANCHOR_BYTES.to_vec()), 2..=3),
        prop::sample::select(GUARD_VAR_CS.to_vec()),
        prop::bool::weighted(0.5),
        1usize..=12,
        prop::option::of(prop::sample::select(GUARD_CS.to_vec())),
        any::<[u8; 32]>(),
    )
        .prop_flat_map(|(lit, cs, trailing, t, guard_cs, salt)| {
            let floor = generators::floor_len(cs);
            (floor..=floor + 4).prop_map(move |n| {
                let mut segs = vec![Seg::Lit(lit.clone()), Seg::Var(cs, n, n)];
                if trailing {
                    segs.push(Seg::Lit(b"_".to_vec()));
                }
                PatternSpec {
                    segs,
                    guard: Some(t),
                    guard_cs,
                    salt,
                    accepted: None,
                }
            })
        })
}

fn wrap_payload(candidate: &[u8], run: &[u8], filler: Vec<u8>, eof: bool) -> Vec<u8> {
    let mut payload = filler;
    payload.extend_from_slice(candidate);
    payload.extend_from_slice(run);
    if !eof {
        payload.push(generators::FILLER[0]);
    }
    payload
}

#[derive(Debug)]
struct GuardCase {
    spec: PatternSpec,
    payload: Vec<u8>,
    candidate_start: usize,
    candidate: Vec<u8>,
    effective_guard_cs: Cs,
    threshold: usize,
    run_in_guard_cs: usize,
}

/// Filler + candidate + run of `t + delta` bytes (effective guard or variable
/// charset) + EOF/FILLER terminator. `run_in_guard_cs` counts the leading run
/// bytes in the effective guard charset.
fn guarded_case() -> BoxedStrategy<GuardCase> {
    arb_guarded_spec()
        .prop_flat_map(|spec| {
            let lit = first_lit(&spec);
            let (var_cs, n) = var_seg(&spec);
            let trailing = spec.segs.len() == 3;
            let threshold = spec.guard.expect("arb_guarded_spec sets a guard");
            let effective = spec.guard_cs.unwrap_or(var_cs);
            let candidate = {
                let lit = lit.clone();
                prop::collection::vec(prop::sample::select(chars_excluding(var_cs, &lit)), n..=n)
                    .prop_map(move |mid| {
                        let mut c = lit.clone();
                        c.extend_from_slice(&mid);
                        if trailing {
                            c.push(b'_');
                        }
                        c
                    })
            };
            let run_sources: Vec<Cs> = if effective == var_cs {
                vec![var_cs]
            } else {
                vec![effective, var_cs]
            };
            let excluded = lit.clone();
            let run = (prop::sample::select(run_sources), -2i32..=2).prop_flat_map(
                move |(run_cs, delta)| {
                    arb_run(
                        run_cs,
                        (threshold as i32 + delta).max(0) as usize,
                        &excluded,
                    )
                },
            );
            let filler =
                prop::collection::vec(prop::sample::select(generators::FILLER.to_vec()), 0..=3);
            let eof = prop::bool::weighted(0.5);
            (candidate, run, filler, eof).prop_map(move |(candidate, run, filler, eof)| {
                let candidate_start = filler.len();
                let payload = wrap_payload(&candidate, &run, filler, eof);
                let run_in_guard_cs = run.iter().take_while(|&&b| effective.contains(b)).count();
                GuardCase {
                    spec: spec.clone(),
                    payload,
                    candidate_start,
                    candidate,
                    effective_guard_cs: effective,
                    threshold,
                    run_in_guard_cs,
                }
            })
        })
        .boxed()
}

proptest! {
    #![proptest_config(crate::support::config(96))]

    #[test]
    fn prop_guard_threshold_boundary_matches_oracle(case in guarded_case()) {
        let (_file, patterns, oracles) = generators::build(std::slice::from_ref(&case.spec));
        prop_assert_eq!(patterns.len(), oracles.len());
        crate::detection::check_swap_against_oracle(&patterns, &oracles, &case.payload)?;

        let result = doppel::swap(&case.payload, &patterns)
            .expect("generated guarded swap must succeed");
        let end = case.candidate_start + case.candidate.len();
        let out_span = &result.payload[case.candidate_start..end];
        // Independent boundary oracle: the planted candidate is replaced iff the
        // leading run in the effective guard charset is shorter than `t`.
        let fires = case.run_in_guard_cs >= case.threshold;
        if fires {
            prop_assert_eq!(
                out_span,
                case.candidate.as_slice(),
                "t={} run_in_guard_cs={} cs={}",
                case.threshold,
                case.run_in_guard_cs,
                case.effective_guard_cs.name()
            );
        } else {
            prop_assert_ne!(
                out_span,
                case.candidate.as_slice(),
                "t={} run_in_guard_cs={} cs={}",
                case.threshold,
                case.run_in_guard_cs,
                case.effective_guard_cs.name()
            );
        }
    }

    #[test]
    fn prop_guarded_ties_and_no_cascade_match_oracle((specs, payload) in tie_case()) {
        let (_file, patterns, oracles) = generators::build(&specs);
        prop_assert_eq!(patterns.len(), oracles.len());
        crate::detection::check_swap_against_oracle(&patterns, &oracles, &payload)?;
    }

    #[test]
    fn prop_secret_inside_probe_window_still_detected(case in probe_window_case()) {
        let (_file, patterns, oracles) = generators::build(&case.specs);
        prop_assert_eq!(patterns.len(), oracles.len());
        crate::detection::check_swap_against_oracle(&patterns, &oracles, &case.payload)?;

        let result = doppel::swap(&case.payload, &patterns)
            .expect("generated probe-window swap must succeed");
        // item 47 / VC-20: A's guard suppresses A, leaving A verbatim.
        prop_assert_eq!(
            &result.payload[case.a_start..case.a_end],
            case.a_candidate.as_slice(),
            "suppressed A must remain unchanged"
        );
        // item 47 / VC-20: B inside A's probe window is detected at its own
        // position and replaced, so its bytes no longer appear.
        prop_assert!(
            !result
                .payload
                .windows(case.b_candidate.len())
                .any(|w| w == case.b_candidate.as_slice()),
            "B inside the probe window must be replaced"
        );
    }

    #[test]
    fn prop_local_specs_meet_fake_capacity_floor(specs in local_specs()) {
        for spec in &specs {
            prop_assert!(
                generators::fake_capacity_bits(&spec.segs)
                    >= generators::FAKE_CAPACITY_FLOOR_BITS,
                "local guard spec below the fake-capacity floor: {:?}",
                spec.segs
            );
        }
    }
}

/// Two or three specs sharing the same first literal, structure and match end,
/// varying guard threshold, guard charset and salt, plus an optional shorter
/// unguarded variant (drop the trailing `_`) to exercise the no-cascade rule.
fn tie_case() -> BoxedStrategy<(Vec<PatternSpec>, Vec<u8>)> {
    arb_guarded_spec()
        .prop_flat_map(|base| {
            let lit = first_lit(&base);
            let (var_cs, n) = var_seg(&base);
            let trailing = base.segs.len() == 3;
            let threshold = base.guard.expect("arb_guarded_spec sets a guard");
            let effective = base.guard_cs.unwrap_or(var_cs);
            let base_segs = base.segs.clone();

            let variant = (
                prop::option::of(1usize..=12),
                prop::option::of(prop::sample::select(GUARD_CS.to_vec())),
                any::<[u8; 32]>(),
            )
                .prop_map({
                    let base_segs = base_segs.clone();
                    move |(guard, guard_cs, salt)| PatternSpec {
                        segs: base_segs.clone(),
                        guard,
                        guard_cs: if guard.is_some() { guard_cs } else { None },
                        salt,
                        accepted: None,
                    }
                });
            let specs = (
                prop::collection::vec(variant, 2..=3),
                prop::option::of(any::<[u8; 32]>()),
            )
                .prop_map({
                    let base_segs = base_segs.clone();
                    move |(mut variants, shorter_salt)| {
                        if let (Some(salt), true) = (shorter_salt, trailing) {
                            let mut segs = base_segs.clone();
                            segs.pop();
                            variants.push(PatternSpec {
                                segs,
                                guard: None,
                                guard_cs: None,
                                salt,
                                accepted: None,
                            });
                        }
                        variants
                    }
                });

            let candidate = {
                let lit = lit.clone();
                prop::collection::vec(prop::sample::select(chars_excluding(var_cs, &lit)), n..=n)
                    .prop_map(move |mid| {
                        let mut c = lit.clone();
                        c.extend_from_slice(&mid);
                        if trailing {
                            c.push(b'_');
                        }
                        c
                    })
            };
            let run_sources: Vec<Cs> = if effective == var_cs {
                vec![var_cs]
            } else {
                vec![effective, var_cs]
            };
            let excluded = lit.clone();
            let run = (prop::sample::select(run_sources), -2i32..=2).prop_flat_map(
                move |(run_cs, delta)| {
                    arb_run(
                        run_cs,
                        (threshold as i32 + delta).max(0) as usize,
                        &excluded,
                    )
                },
            );
            let filler =
                prop::collection::vec(prop::sample::select(generators::FILLER.to_vec()), 0..=3);
            let eof = prop::bool::weighted(0.5);
            (specs, candidate, run, filler, eof).prop_map(
                move |(specs, candidate, run, filler, eof)| {
                    (specs, wrap_payload(&candidate, &run, filler, eof))
                },
            )
        })
        .boxed()
}

#[derive(Debug)]
struct ProbeCase {
    specs: Vec<PatternSpec>,
    payload: Vec<u8>,
    a_start: usize,
    a_end: usize,
    a_candidate: Vec<u8>,
    b_candidate: Vec<u8>,
}

/// Guarded spec A whose suppressing run contains a full unguarded candidate of
/// spec B. A's explicit guard charset (`wide`/`base64_any`) contains B's `PQ`
/// anchor, so the run suppresses A while B is still detected at its own start.
fn probe_window_case() -> BoxedStrategy<ProbeCase> {
    (
        prop::collection::vec(prop::sample::select(A_ANCHOR_BYTES.to_vec()), 2..=3),
        prop::sample::select(GUARD_VAR_CS.to_vec()),
        1usize..=12,
        prop::collection::vec(prop::sample::select(B_ANCHOR_BYTES.to_vec()), 2..=2),
        prop::sample::select(B_VAR_CS.to_vec()),
        prop::sample::select(A_GUARD_CS.to_vec()),
        any::<[u8; 32]>(),
        any::<[u8; 32]>(),
        prop::collection::vec(prop::sample::select(generators::FILLER.to_vec()), 0..=2),
    )
        .prop_flat_map(
            |(a_lit, a_cs, threshold, b_anchor, b_cs, guard_cs, a_salt, b_salt, prefix)| {
                let excluded: Vec<u8> = a_lit.iter().chain(b_anchor.iter()).copied().collect();
                let a_floor = generators::floor_len(a_cs);
                let b_floor = generators::floor_len(b_cs);
                (
                    0usize..=3,
                    0usize..=3,
                    prop::bool::weighted(0.5),
                    a_floor..=a_floor + 4,
                    b_floor..=b_floor + 4,
                )
                    .prop_flat_map(move |(offset, extra, eof, a_n, b_n)| {
                        let base_run = offset + b_anchor.len() + b_n;
                        let pad_after = threshold.saturating_sub(base_run) + extra;
                        let before = arb_run(guard_cs, offset, &excluded);
                        let after = arb_run(guard_cs, pad_after, &excluded);
                        let a_mid = prop::collection::vec(
                            prop::sample::select(chars_excluding(a_cs, &excluded)),
                            a_n..=a_n,
                        );
                        let b_mid = prop::collection::vec(
                            prop::sample::select(chars_excluding(b_cs, &excluded)),
                            b_n..=b_n,
                        );
                        let a_lit = a_lit.clone();
                        let b_anchor = b_anchor.clone();
                        let prefix = prefix.clone();
                        (a_mid, b_mid, before, after).prop_map(
                            move |(a_mid, b_mid, before, after)| {
                                let mut a_cand = a_lit.clone();
                                a_cand.extend_from_slice(&a_mid);
                                let mut b_cand = b_anchor.clone();
                                b_cand.extend_from_slice(&b_mid);
                                let mut run = before;
                                run.extend_from_slice(&b_cand);
                                run.extend_from_slice(&after);
                                let mut payload = prefix.clone();
                                let a_start = payload.len();
                                payload.extend_from_slice(&a_cand);
                                let a_end = payload.len();
                                payload.extend_from_slice(&run);
                                if !eof {
                                    payload.push(generators::FILLER[0]);
                                }
                                let specs = vec![
                                    PatternSpec {
                                        segs: vec![
                                            Seg::Lit(a_lit.clone()),
                                            Seg::Var(a_cs, a_n, a_n),
                                        ],
                                        guard: Some(threshold),
                                        guard_cs: Some(guard_cs),
                                        salt: a_salt,
                                        accepted: None,
                                    },
                                    PatternSpec {
                                        segs: vec![
                                            Seg::Lit(b_anchor.clone()),
                                            Seg::Var(b_cs, b_n, b_n),
                                        ],
                                        guard: None,
                                        guard_cs: None,
                                        salt: b_salt,
                                        accepted: None,
                                    },
                                ];
                                ProbeCase {
                                    specs,
                                    payload,
                                    a_start,
                                    a_end,
                                    a_candidate: a_cand,
                                    b_candidate: b_cand,
                                }
                            },
                        )
                    })
            },
        )
        .boxed()
}

/// Every spec produced by this module's local strategies. Used by
/// `prop_local_specs_meet_fake_capacity_floor` to prove none can rely on
/// sub-floor fake collisions (D5 = A).
fn local_specs() -> BoxedStrategy<Vec<PatternSpec>> {
    prop_oneof![
        arb_guarded_spec().prop_map(|spec| vec![spec]),
        probe_window_case().prop_map(|case| case.specs),
        tie_case().prop_map(|(specs, _)| specs),
    ]
    .boxed()
}

/// Coverage guard, not a correctness check: property 1 must see both suppressed
/// and replaced candidates. Fixed seed via `TestRunner::deterministic`.
#[test]
fn prop_guard_boundary_covers_both_outcomes() {
    use proptest::test_runner::TestRunner;

    const CASES: u32 = 512;
    let strategy = guarded_case();
    let mut runner = TestRunner::deterministic();

    let mut suppressed = 0u32;
    let mut replaced = 0u32;
    for _ in 0..CASES {
        let case = strategy
            .new_tree(&mut runner)
            .expect("coverage sample must generate a case")
            .current();
        if case.run_in_guard_cs >= case.threshold {
            suppressed += 1;
        } else {
            replaced += 1;
        }
    }
    println!(
        "guard boundary coverage over {CASES} cases: suppressed={suppressed} replaced={replaced}"
    );
    assert!(
        suppressed * 5 >= CASES,
        "suppressed share below 20%: {suppressed}/{CASES}"
    );
    assert!(
        replaced * 5 >= CASES,
        "replaced share below 20%: {replaced}/{CASES}"
    );
}
